  'التوقيع: ..................': 'Signature : ..................',
  'إنه في يوم {تاريخ تحرير العقد} بمدينة {مكان تحرير العقد} تم الاتفاق بين كلٍّ من الطرف الأول (المؤجر): {اسم المؤجر}، والطرف الثاني (المستأجر): {اسم المستأجر}، وقد أقرّ الطرفان بأهليتهما للتعاقد واتفقا على ما يلي:': 'Le {تاريخ تحرير العقد} à {مكان تحرير العقد}, un accord a été conclu entre la première partie (bailleur) : {اسم المؤجر}, et la seconde partie (locataire) : {اسم المستأجر}. Les deux parties reconnaissent leur capacité juridique à contracter et conviennent de ce qui suit :',
  'أقرّ أنا الموقّع أدناه {اسم المدين}، حامل الهوية رقم {رقم هوية المدين}، بأنني استلمت من {اسم الدائن}، حامل الهوية رقم {رقم هوية الدائن}، مبلغًا وقدره {المبلغ} ({المبلغ كتابةً}) على سبيل {نوع المبلغ}، وذلك بتاريخ {تاريخ الاستلام}.': 'Je soussigné(e) {اسم المدين}, titulaire de la pièce d\'identité n° {رقم هوية المدين}, reconnais avoir reçu de {اسم الدائن}, titulaire de la pièce d\'identité n° {رقم هوية الدائن}, la somme de {المبلغ} ({المبلغ كتابةً}) à titre de {نوع المبلغ}, le {تاريخ الاستلام}.',
  'إنه في يوم {تاريخ تحرير العقد} تم الاتفاق بين كلٍّ من الطرف الأول: {الطرف الأول}، والطرف الثاني: {الطرف الثاني}، وقد أقرّ الطرفان بأهليتهما للتعاقد واتفقا على ما يلي:': 'Le {تاريخ تحرير العقد}, un accord a été conclu entre la première partie : {الطرف الأول}, et la seconde partie : {الطرف الثاني}. Les deux parties reconnaissent leur capacité juridique à contracter et conviennent de ce qui suit :',
  'دفع المستأجر مبلغ تأمين قدره {مبلغ التأمين}، يُردّ إليه عند انتهاء العقد بعد خصم قيمة أي أضرار أو مستحقات قائمة.': 'Le locataire a versé un dépôt de garantie de {مبلغ التأمين}, remboursable à la fin du contrat après déduction des éventuels dommages ou sommes dues.',
  'شروط إضافية: {شروط إضافية}': 'Conditions supplémentaires : {شروط إضافية}',
  'حُرِّر هذا العقد من نسختين، بيد كل طرف نسخة للعمل بموجبها.': 'Le présent contrat est établi en deux exemplaires, un pour chaque partie.',
  'مدة العقد من {تاريخ بداية العقد} إلى {تاريخ نهاية العقد}، ولا يُجدَّد إلا باتفاق مكتوب بين الطرفين.': 'La durée du contrat va du {تاريخ بداية العقد} au {تاريخ نهاية العقد} ; il n\'est renouvelé que par accord écrit entre les parties.',
  'الأجرة السنوية {قيمة الإيجار السنوي}، تُدفع {طريقة الدفع} مقدمًا في مواعيد استحقاقها، ولا يحق للمستأجر تأخيرها أو الامتناع عنها.': 'Le loyer annuel est de {قيمة الإيجار السنوي}, payable d\'avance ({طريقة الدفع}) aux échéances prévues ; le locataire ne peut ni le retarder ni le retenir.',
  'إذا تأخر المستأجر عن سداد الأجرة أو أخلّ بأي من التزاماته، يحق للمؤجر المطالبة بفسخ العقد وبما يستحقه وفق الأنظمة المعمول بها.': 'Si le locataire paie le loyer en retard ou manque à l\'une de ses obligations, le bailleur peut demander la résiliation du contrat et les sommes dues conformément à la loi applicable.',
  'سبب الدين: {سبب الدين}.': 'Motif de la dette : {سبب الدين}.',
  'أتعهد بردّ المبلغ كاملًا إلى الدائن أو من يفوّضه في موعد أقصاه {تاريخ السداد}، وطريقة السداد: {طريقة السداد}.': 'Je m\'engage à rembourser l\'intégralité du montant au créancier ou à son représentant autorisé au plus tard le {تاريخ السداد}. Mode de remboursement : {طريقة السداد}.',
  'يُسدَّد المبلغ على {عدد الأقساط} أقساط، قيمة كل قسط {قيمة القسط}.': 'Le montant est remboursé en {عدد الأقساط} échéances de {قيمة القسط} chacune.',
  'يُعدّ هذا الإيصال سندًا بالمبلغ، ويحق للدائن عند التأخر عن السداد المطالبة به بالطرق النظامية.': 'Le présent reçu vaut preuve de la dette ; en cas de retard de remboursement, le créancier peut la réclamer par les voies légales.',
  'وهذا إقرار مني بذلك وأنا بكامل أهليتي المعتبرة شرعًا ونظامًا.': 'Je fais cette reconnaissance en pleine capacité juridique.',
  'يستعمل المستأجر العقار للغرض المتفق عليه ({الغرض من الإيجار}) فقط، ولا يحق له التأجير من الباطن أو التنازل عن العقد إلا بموافقة كتابية من المؤجر.': 'Le locataire utilisera le bien uniquement pour l\'usage convenu ({الغرض من الإيجار}) et ne peut ni sous-louer ni céder le contrat sans l\'accord écrit du bailleur.',
  'فواتير الخدمات (الكهرباء والماء والاتصالات) على {فواتير الخدمات على}، والصيانة البسيطة على {الصيانة البسيطة على}، والصيانة الأساسية والإنشائية على {الصيانة الأساسية على}.': 'Les factures des services (électricité, eau et télécommunications) sont à la charge du {فواتير الخدمات على} ; le petit entretien à la charge du {الصيانة البسيطة على} ; le gros entretien et les travaux structurels à la charge du {الصيانة الأساسية على}.',
  'لا يجوز للمستأجر إجراء أي تعديلات أو إنشاءات في العقار إلا بموافقة كتابية من المؤجر.': 'Le locataire ne peut effectuer aucune modification ni construction dans le bien sans l\'accord écrit du bailleur.',
  'يلتزم المستأجر بالمحافظة على العقار وتسليمه عند انتهاء العقد بالحالة التي استلمه بها، عدا الاستهلاك المعتاد.': 'Le locataire doit entretenir le bien et le restituer à la fin du contrat dans l\'état où il l\'a reçu, hors usure normale.',
  'منح المؤجر المستأجر فترة سماح للتجهيز مدتها {فترة السماح للتجهيز} لا تُحتسب فيها أجرة.': 'Le bailleur accorde au locataire une période de franchise pour aménagement de {فترة السماح للتجهيز}, sans loyer.',
  'يستعمل المستأجر المحل لممارسة نشاط ({نوع النشاط}) تحت الاسم التجاري ({الاسم التجاري}) فقط، ولا يحق له تغيير النشاط أو التأجير من الباطن إلا بموافقة كتابية من المؤجر.': 'Le locataire utilisera le local uniquement pour l\'activité ({نوع النشاط}) sous le nom commercial ({الاسم التجاري}) et ne peut ni changer d\'activité ni sous-louer sans l\'accord écrit du bailleur.',
  'يلتزم المستأجر باستخراج التراخيص اللازمة لنشاطه وتجديدها قبل انتهائها، ويتحمّل وحده أي مخالفات أو غرامات تنشأ عن نشاطه.': 'Le locataire doit obtenir les licences nécessaires à son activité et les renouveler avant leur expiration ; il supporte seul les infractions ou amendes liées à son activité.',
  'فواتير الخدمات على {فواتير الخدمات على}، والصيانة على {الصيانة على}، واللوحات والديكور على {اللوحات والديكور على}.': 'Les factures des services sont à la charge du {فواتير الخدمات على} ; l\'entretien à la charge du {الصيانة على} ; les enseignes et la décoration à la charge du {اللوحات والديكور على}.',
  'عند انتهاء العقد يسلّم المستأجر المحل خاليًا من الشواغل وبالحالة التي استلمه بها، وتؤول التحسينات الثابتة للمؤجر ما لم يُتفق على غير ذلك.': 'À la fin du contrat, le locataire restitue le local libre de tout occupant et dans l\'état où il l\'a reçu ; les améliorations fixes reviennent au bailleur sauf accord contraire.',
  'مدة الإيجار من {تاريخ بداية العقد} إلى {تاريخ نهاية العقد}، وأجرة المركبة {قيمة الإيجار} على أساس {أساس التأجير}.': 'La période de location va du {تاريخ بداية العقد} au {تاريخ نهاية العقد}, et le loyer du véhicule est de {قيمة الإيجار} sur une base {أساس التأجير}.',
  'دفع المستأجر مبلغ تأمين قدره {مبلغ التأمين}، يُردّ عند إعادة المركبة سليمة بعد خصم أي مستحقات.': 'Le locataire a versé un dépôt de garantie de {مبلغ التأمين}, remboursable à la restitution du véhicule en bon état après déduction des sommes dues.',
  'استلم المستأجر المركبة بحالة جيدة، وقراءة العداد {قراءة العداد عند التسليم} كم، ومستوى الوقود {مستوى الوقود عند التسليم}، ويعيدها بالحالة نفسها.': 'Le locataire a reçu le véhicule en bon état avec un compteur de {قراءة العداد عند التسليم} km et un niveau de carburant {مستوى الوقود عند التسليم}, et le restituera dans le même état.',
  'الكيلومترات المسموحة {الكيلومترات المسموحة} كم، وما زاد عليها يُحتسب بواقع {رسوم الكيلومتر الإضافي} لكل كيلومتر.': 'La distance autorisée est de {الكيلومترات المسموحة} km ; tout dépassement est facturé {رسوم الكيلومتر الإضافي} par kilomètre.',
  'المستأجر مسؤول عن المخالفات المرورية والحوادث وما يترتب عليها طوال مدة الإيجار، وعليه إبلاغ المؤجر والجهات المختصة فور وقوع أي حادث.': 'Le locataire est responsable des infractions routières, des accidents et de leurs conséquences pendant la période de location, et doit avertir le bailleur et les autorités immédiatement après tout accident.',
  'لا يحق للمستأجر السماح لغيره بقيادة المركبة، أو استعمالها في غير الغرض المعتاد، أو الخروج بها خارج الدولة إلا بموافقة كتابية من المؤجر.': 'Le locataire ne peut pas laisser d\'autres personnes conduire le véhicule, l\'utiliser à des fins inhabituelles ni le sortir du pays sans l\'accord écrit du bailleur.',
  'الوقود على {الوقود على}، والصيانة الدورية على {الصيانة الدورية على}، ونوع التأمين على المركبة: {التأمين على المركبة}.': 'Le carburant est à la charge du {الوقود على} ; l\'entretien courant à la charge du {الصيانة الدورية على} ; assurance du véhicule : {التأمين على المركبة}.',
  'التأخر في إعادة المركبة عن الموعد المحدد يُحتسب بأجرة يوم كامل عن كل يوم تأخير أو جزء منه.': 'Tout retard de restitution du véhicule est facturé une journée complète de loyer par jour ou fraction de jour de retard.',
  'موضوع العقد: {موضوع العقد}': 'Objet du contrat : {موضوع العقد}',
