  'اختر الصفحة التي تريد تخصيصها: أخفِ ما لا تستخدمه من فئات، ويعود كل شيء متى أظهرته.': 'Choisissez une page à personnaliser : masquez les catégories inutilisées ; tout réapparaît dès que vous les affichez.',
  'أخفِ الفئة كاملة بمفتاحها. المخفي يختفي من الصفحة وقوائم الإضافة والعدّادات، وبياناته لا تُحذف.': 'Masquez une catégorie entière avec son interrupteur. Les éléments masqués disparaissent de la page, des menus d\'ajout et des compteurs ; leurs données ne sont pas supprimées.',
