  'اختر الصفحة التي تريد تخصيصها: أخفِ ما لا تستخدمه من فئات أو عناصر داخلها، ويعود كل شيء متى أظهرته.': 'Choisissez une page à personnaliser : masquez les catégories ou éléments inutilisés ; tout réapparaît dès que vous les affichez.',
