  'ظاهرة في الصفحة': 'Visible sur la page',
  'أخفِ فئة كاملة بمفتاحها، أو افتح الفئة وأخفِ عناصر محددة داخلها. المخفي يختفي من الصفحة وقوائم الإضافة والعدّادات، وبياناته لا تُحذف.': 'Masquez une catégorie entière avec son interrupteur, ou ouvrez-la pour masquer des éléments précis. Ce qui est masqué disparaît de la page, des menus d\'ajout et des compteurs ; les données ne sont pas supprimées.',
