  'اكتب ما تم الاتفاق عليه في التسوية': 'Indiquez ce qui a été convenu lors du règlement',
  'يرجى الإلغاء بعد عمل التسوية.': 'Veuillez annuler uniquement après le règlement.',
  'سيصبح العقد «ملغي» وتتحول الوحدة إلى شاغرة. هل تريد المتابعة؟\n\nتنبيه: بعد الإلغاء تختفي معلومات هذا العقد ومستحقاته من التقارير. إذا كنت تحتاج الوحدة أو معلوماتها مستقبلًا فالأفضل «الأرشفة» بدل الإلغاء.': 'Le contrat passera à « Annulé » et le lot deviendra vacant. Continuer ?\n\nRemarque : après l\'annulation, ce contrat et ses échéances disparaissent des rapports. Si vous aurez besoin du lot ou de ses informations plus tard, mieux vaut archiver qu\'annuler.',
  'أُلغي العقد وأصبحت الوحدة شاغرة': 'Contrat annulé, le lot est désormais vacant',
  'تعذر إلغاء العقد': 'Impossible d\'annuler le contrat',
  'الوحدة شاغرة ولا يوجد عقد لإلغائه': 'Le lot est vacant ; aucun contrat à annuler',
  'سيُلغى عقد الإيجار بعد عمل التسوية، ويصبح العقد «ملغي» والوحدة شاغرة. هل تريد المتابعة؟\n\nتنبيه: بعد الإلغاء تختفي معلومات هذا العقد ومستحقاته من التقارير. إذا كنت تحتاج الوحدة أو معلوماتها مستقبلًا فالأفضل «الأرشفة» بدل الإلغاء.': 'Le bail sera annulé après le règlement ; le contrat passera à « Annulé » et le lot deviendra vacant. Continuer ?\n\nRemarque : après l\'annulation, ce contrat et ses échéances disparaissent des rapports. Si vous aurez besoin du lot ou de ses informations plus tard, mieux vaut archiver qu\'annuler.',
