  'الدفع داخل التطبيق لم يُفعَّل بعد، فتُفعَّل الباقة الآن تجريبيًا بلا أي خصم. تتغير صلاحيات الأقسام فورًا.': 'Le paiement intégré n\'est pas encore activé : le forfait est activé maintenant à l\'essai, sans aucun prélèvement. Les droits des sections changent immédiatement.',
