  'إدخال بلا حد': 'Saisie illimitée',
  'إدخال محدود': 'Saisie limitée',
  'آخر تحديث: 12 أكتوبر 2026': 'Dernière mise à jour : 12 octobre 2026',
  'توضح هذه السياسة كيف يجمع تطبيق Fundly بياناتك ويستخدمها ويحميها، وحقوقك عليها. باستخدامك التطبيق فأنت توافق على ما ورد فيها.': 'La présente politique explique comment l\'application Fundly collecte, utilise et protège vos données, ainsi que les droits dont vous disposez à leur égard. En utilisant l\'Application, vous acceptez les dispositions qui y figurent.',
  'من نحن ونطاق السياسة': 'Qui sommes-nous et champ d\'application de la politique',
  'تطبيق Fundly («التطبيق»، «نحن») لإدارة الأموال والالتزامات والأصول والعلاقات. تسري هذه السياسة على كل ما يُجمع أو يُعالَج عبر التطبيق وخدماته، وتُطبَّق وفق نظام حماية البيانات الشخصية في المملكة العربية السعودية ولائحته التنفيذية، وأنظمة حماية البيانات المعمول بها في بلد المستخدم بالقدر الذي ينطبق عليه.': 'Fundly (« l\'Application », « nous ») est une application de gestion des finances, des engagements, des actifs et des relations. La présente politique s\'applique à toutes les données collectées ou traitées par l\'intermédiaire de l\'Application et de ses services, et est appliquée conformément à la Loi sur la protection des données personnelles (PDPL) du Royaume d\'Arabie saoudite et à son règlement d\'application, ainsi qu\'aux lois sur la protection des données en vigueur dans le pays de l\'utilisateur, dans la mesure où elles lui sont applicables.',
  'البيانات التي نجمعها': 'Données que nous collectons',
  '• بيانات الحساب: الاسم، ورقم الهاتف أو البريد الإلكتروني المستخدم في الدخول، والرقم التعريفي الذي يُنشئه التطبيق لك.\n• البيانات التي تدخلها بنفسك: الالتزامات والمصروفات والدخل والديون والعهد والأقساط، وبيانات العقارات والأنشطة والمركبات وعقود الإيجار والدفعات، والمستندات والمرفقات والنماذج والتقارير.\n• بيانات أشخاص آخرين تسجّلها أنت: مثل المستأجرين والمؤجرين والأفراد والجهات وأرقام هوياتهم وهواتفهم.\n• الموقع الجغرافي: عند ضغطك زر جلب الموقع فقط، وبعد إذنك.\n• بيانات تقنية محدودة يلزمها التشغيل، مثل سجلات الاتصال لدى مزوّد الاستضافة لأغراض الأمان.\nلا نستخدم أدوات إعلانات أو تتبّع أو تحليلات سلوكية من أطراف ثالثة.': '• Données du compte : votre nom, le numéro de téléphone ou l\'adresse e-mail utilisé pour vous connecter, et le numéro d\'identification que l\'Application génère pour vous.\n• Données que vous saisissez vous-même : engagements, dépenses, revenus, dettes, avances confiées et échéances ; données relatives aux biens immobiliers, aux activités, aux véhicules, aux contrats de location et aux paiements ; ainsi que documents, pièces jointes, modèles et rapports.\n• Données d\'autres personnes que vous enregistrez : par exemple locataires, bailleurs, particuliers et organismes, ainsi que leurs numéros d\'identité et de téléphone.\n• Localisation géographique : uniquement lorsque vous appuyez sur le bouton « Obtenir la position », et avec votre autorisation.\n• Données techniques limitées nécessaires au fonctionnement, telles que les journaux de connexion conservés par l\'hébergeur à des fins de sécurité.\nNous n\'utilisons aucun outil tiers de publicité, de suivi ou d\'analyse comportementale.',
  'لماذا نعالج بياناتك': 'Pourquoi nous traitons vos données',
  '• تقديم خدمات التطبيق وحفظ سجلاتك ومزامنتها بين أجهزتك.\n• إنشاء التذكيرات والتنبيهات والتقارير التي تطلبها.\n• تنفيذ المشاركة التي تختارها مع مستخدمين آخرين (العهد والديون والالتزامات المشتركة والتفويضات).\n• الرد على طلبات الدعم.\n• حماية الحسابات ومنع الاستخدام غير المشروع والالتزام بالأنظمة.\nنعالج البيانات لتنفيذ الخدمة التي طلبتها، وبموافقتك فيما يحتاج موافقة (الموقع والكاميرا والصور)، وللوفاء بالتزاماتنا النظامية. ولا نستخدمها لأي غرض آخر دون إبلاغك.': '• Fournir les services de l\'Application, conserver vos enregistrements et les synchroniser entre vos appareils.\n• Générer les rappels, alertes et rapports que vous demandez.\n• Mettre en œuvre le partage que vous choisissez avec d\'autres utilisateurs (avances confiées, dettes, engagements partagés et délégations).\n• Répondre aux demandes d\'assistance.\n• Protéger les comptes, prévenir toute utilisation illicite et respecter la réglementation.\nNous traitons les données pour exécuter le service que vous avez demandé, sur la base de votre consentement lorsque celui-ci est requis (localisation, appareil photo et photos), et pour respecter nos obligations légales. Nous ne les utilisons à aucune autre fin sans vous en informer.',
  'أين تُحفظ بياناتك': 'Où vos données sont conservées',
  '• السجلات الأساسية والمرفقات المرفوعة تُحفظ لدى مزوّد الاستضافة السحابية (Supabase)، مقيّدة بحسابك بضوابط وصول على مستوى السجل، فلا يطّلع عليها حساب آخر إلا ما تشاركه أنت.\n• تُحفظ على جهازك فقط: التفضيلات، وصورة الملف الشخصي، ورمز قفل التطبيق، والتوقيع والختم والشعار، ودليل الأفراد والجهات، والمستندات العامة، والتذكيرات المحلية. حذف التطبيق يحذف هذه البيانات من الجهاز.\n• قد تُعالَج البيانات على خوادم خارج بلدك، ونلتزم عندئذ بالضمانات التي تشترطها الأنظمة لنقل البيانات خارج الحدود.': '• Les enregistrements principaux et les pièces jointes téléversées sont conservés chez notre hébergeur cloud (Supabase) et restreints à votre compte au moyen de contrôles d\'accès au niveau de chaque enregistrement, de sorte qu\'aucun autre compte ne peut les consulter, hormis ce que vous partagez vous-même.\n• Sont conservés uniquement sur votre appareil : les préférences, la photo de profil, le code de verrouillage de l\'Application, la signature, le cachet et le logo, le répertoire des particuliers et organismes, les documents généraux et les rappels locaux. La suppression de l\'Application efface ces données de l\'appareil.\n• Les données peuvent être traitées sur des serveurs situés hors de votre pays ; nous respectons alors les garanties exigées par la réglementation pour les transferts transfrontaliers de données.',
  'مشاركة البيانات والإفصاح عنها': 'Partage et divulgation des données',
  '• لا نبيع بياناتك ولا نؤجّرها ولا نشاركها لأغراض تسويقية.\n• المشاركة داخل التطبيق تتم بطلبك: عند إسناد عهدة أو دين أو إضافة عضو بالرقم التعريفي يرى الطرف الآخر العنصر المشترك واسمك فقط، ولا يُكشف هاتفك أو عنوانك إلا بموافقتك.\n• ما تشاركه عبر زر المشاركة أو الطباعة (PDF أو صورة) يخرج بإرادتك وعبر التطبيق الذي تختاره.\n• نستعين بمزوّدي خدمة (الاستضافة والتخزين) يعالجون البيانات نيابةً عنّا وفق التزامات تعاقدية بالسرية والأمان.\n• قد نفصح عن البيانات إذا ألزمنا بذلك نظام أو أمر قضائي أو جهة مختصة.': '• Nous ne vendons ni ne louons vos données, et nous ne les partageons pas à des fins de marketing.\n• Le partage au sein de l\'Application s\'effectue à votre demande : lorsque vous attribuez une avance confiée ou une dette, ou ajoutez un membre au moyen de son numéro d\'identification, l\'autre partie ne voit que l\'élément partagé et votre nom ; votre numéro de téléphone ou votre adresse ne sont divulgués qu\'avec votre consentement.\n• Ce que vous partagez au moyen du bouton de partage ou d\'impression (PDF ou image) quitte l\'Application de votre propre initiative et par l\'application que vous choisissez.\n• Nous faisons appel à des prestataires de services (hébergement et stockage) qui traitent les données pour notre compte, dans le cadre d\'obligations contractuelles de confidentialité et de sécurité.\n• Nous pouvons divulguer des données lorsqu\'une loi, une décision judiciaire ou une autorité compétente nous y oblige.',
  '• الكاميرا والصور والملفات: لإرفاق المستندات والصور والختم والشعار وصورة الملف الشخصي.\n• الموقع: لتعبئة حقل الموقع عند طلبك فقط.\n• الإنترنت: لمزامنة بياناتك.\nيمكنك سحب أي إذن من إعدادات جهازك في أي وقت، وتبقى بقية خصائص التطبيق تعمل.': '• Appareil photo, photos et fichiers : pour joindre des documents, des images, le cachet, le logo et la photo de profil.\n• Localisation : pour renseigner le champ de localisation, uniquement à votre demande.\n• Internet : pour synchroniser vos données.\nVous pouvez retirer toute autorisation à tout moment depuis les paramètres de votre appareil ; les autres fonctionnalités de l\'Application continueront de fonctionner.',
  'الاحتفاظ بالبيانات': 'Conservation des données',
  'نحتفظ ببياناتك ما دام حسابك قائمًا. ما تحذفه ينتقل إلى سلة المهملات حتى تحذفه نهائيًا. وعند حذف الحساب تُحذف بياناته من أنظمتنا خلال مدة لا تتجاوز 30 يومًا، عدا ما يلزم الاحتفاظ به نظامًا، وتُزال من النسخ الاحتياطية وفق دورتها.': 'Nous conservons vos données tant que votre compte est actif. Les éléments que vous supprimez sont placés dans la corbeille jusqu\'à leur suppression définitive. En cas de suppression du compte, ses données sont effacées de nos systèmes dans un délai n\'excédant pas 30 jours, à l\'exception de celles dont la conservation est légalement requise, et sont retirées des sauvegardes selon leur cycle de rotation.',
  'أمن البيانات': 'Sécurité des données',
  '• تشفير الاتصال بين التطبيق والخوادم (TLS).\n• ضوابط وصول تقصر كل سجل على صاحبه ومن يشاركه.\n• قفل التطبيق برمز، وخيار إخفاء المبالغ.\nلا توجد وسيلة نقل أو تخزين آمنة تمامًا، لذا نوصيك بحماية جهازك وعدم مشاركة رمز القفل.': '• Chiffrement de la connexion entre l\'Application et les serveurs (TLS).\n• Contrôles d\'accès limitant chaque enregistrement à son propriétaire et aux personnes avec lesquelles il est partagé.\n• Verrouillage de l\'Application par code et option de masquage des montants.\nAucun moyen de transmission ou de stockage n\'est totalement sécurisé ; nous vous recommandons donc de protéger votre appareil et de ne pas communiquer votre code de verrouillage.',
  'حقوقك': 'Vos droits',
  'وفق الأنظمة المعمول بها لك الحق في:\n• العلم بكيفية جمع بياناتك ومعالجتها.\n• الوصول إلى بياناتك والحصول على نسخة منها.\n• تصحيحها أو تحديثها.\n• طلب حذفها أو إتلافها.\n• الرجوع عن موافقتك فيما بُني عليها.\n• تقديم شكوى إلى الجهة المختصة بحماية البيانات في بلدك (في المملكة العربية السعودية: الهيئة السعودية للبيانات والذكاء الاصطناعي «سدايا»).\nنرد على طلبك خلال 30 يومًا من استلامه.': 'Conformément à la réglementation applicable, vous avez le droit :\n• d\'être informé de la manière dont vos données sont collectées et traitées ;\n• d\'accéder à vos données et d\'en obtenir une copie ;\n• de les faire rectifier ou mettre à jour ;\n• de demander leur suppression ou leur destruction ;\n• de retirer votre consentement lorsque le traitement est fondé sur celui-ci ;\n• d\'introduire une réclamation auprès de l\'autorité de protection des données compétente de votre pays (au Royaume d\'Arabie saoudite : l\'Autorité saoudienne des données et de l\'intelligence artificielle (SDAIA)).\nNous répondons à votre demande dans un délai de 30 jours à compter de sa réception.',
  'حذف الحساب': 'Suppression du compte',
  'يمكنك حذف أي سجل من داخل شاشته في أي وقت. ولحذف حسابك وكل بياناته استخدم زر «طلب حذف الحساب» أسفل هذه الصفحة، أو راسلنا على بريد الدعم من البريد أو الرقم المرتبط بحسابك، وسنتحقق من الطلب وننفّذه.': 'Vous pouvez à tout moment supprimer tout enregistrement depuis son écran. Pour supprimer votre compte et l\'ensemble de ses données, utilisez le bouton « Demander la suppression du compte » en bas de cette page, ou écrivez-nous à l\'adresse e-mail d\'assistance depuis l\'adresse e-mail ou le numéro associé à votre compte ; nous vérifierons la demande et y donnerons suite.',
  'بيانات الآخرين التي تدخلها': 'Données de tiers que vous saisissez',
  'عند تسجيلك بيانات أشخاص آخرين (كالمستأجرين أو الأفراد أو أطراف العقود) فأنت مسؤول عن أن يكون لديك أساس نظامي لذلك، وأن تستخدمها لأغراضك المشروعة فقط.': 'Lorsque vous enregistrez des données concernant d\'autres personnes (telles que des locataires, des particuliers ou des parties à des contrats), il vous incombe de disposer d\'une base légale pour ce faire et de ne les utiliser qu\'à des fins légitimes.',
  'الاشتراكات والمدفوعات': 'Abonnements et paiements',
  'عند تفعيل الاشتراكات المدفوعة تتم عمليات الدفع عبر متاجر التطبيقات أو بوابات دفع مرخّصة، ولا نحفظ بيانات بطاقتك.': 'Lorsque les abonnements payants sont activés, les paiements sont effectués via les boutiques d\'applications ou des passerelles de paiement agréées, et nous ne conservons pas les données de votre carte.',
  'الأطفال': 'Enfants',
  'التطبيق موجّه لمن بلغ 18 عامًا، ولا نجمع عن قصد بيانات من هم دون ذلك.': 'L\'Application est destinée aux personnes âgées de 18 ans et plus, et nous ne collectons pas sciemment de données concernant des personnes n\'ayant pas atteint cet âge.',
  'التعديلات على السياسة': 'Modifications de la politique',
  'قد نحدّث هذه السياسة، ونُبلغك داخل التطبيق بأي تغيير جوهري قبل سريانه. واستمرارك في الاستخدام بعد السريان يعني موافقتك على النسخة المحدّثة.': 'Nous pouvons mettre à jour la présente politique et vous informerons dans l\'Application de toute modification substantielle avant son entrée en vigueur. La poursuite de votre utilisation après cette entrée en vigueur vaut acceptation de la version mise à jour.',
  'التواصل معنا': 'Nous contacter',
  'لأي سؤال أو طلب يتعلق بخصوصيتك راسلنا على بريد الدعم: support@fundly.app': 'Pour toute question ou demande relative à votre vie privée, écrivez-nous à notre adresse e-mail d\'assistance : support@fundly.app',
  'طلب حذف الحساب': 'Demander la suppression du compte',
  'سيُفتح بريدك برسالة جاهزة لطلب حذف حسابك وكل بياناته نهائيًا. أرسلها من البريد أو الرقم المرتبط بحسابك. هل تريد المتابعة؟': 'Votre messagerie va s\'ouvrir avec un message prérempli demandant la suppression définitive de votre compte et de l\'ensemble de ses données. Envoyez-le depuis l\'adresse e-mail ou le numéro associé à votre compte. Voulez-vous continuer ?',
  'تعذّر فتح البريد — نُسخ بريد الدعم لتراسلنا منه': 'Impossible d\'ouvrir la messagerie — l\'adresse e-mail d\'assistance a été copiée pour que vous puissiez nous écrire',
