  'كل مصروف يرسله المستلم يصلك لتعتمده أو ترفضه، ولا يُخصم من العهدة قبل اعتماده.': 'Chaque dépense envoyée par le bénéficiaire vous parvient pour approbation ou refus, et n\'est pas déduite de l\'avance avant approbation.',
  'مصروفات المستلم تُخصم من العهدة مباشرة بلا موافقة.': 'Les dépenses du bénéficiaire sont déduites de l\'avance directement, sans approbation.',
  'العهدة مسندة — الصرف عند الطرف الآخر، وكل مصروف يرسله يصلك هنا لتعتمده أو ترفضه.': 'L\'avance est attribuée — les dépenses sont faites par l\'autre partie, et chaque dépense envoyée vous parvient ici pour approbation ou refus.',
