  'يمكنك حذف أي سجل من داخل شاشته في أي وقت. ولحذف حسابك وكل بياناته استخدم «حذف الحساب» في الإعدادات تحت «تسجيل الخروج»، أو راسلنا على بريد الدعم من البريد أو الرقم المرتبط بحسابك، وسنتحقق من الطلب وننفّذه.': 'Vous pouvez supprimer tout enregistrement depuis son écran à tout moment. Pour supprimer votre compte et toutes ses données, utilisez « Supprimer le compte » dans les Paramètres sous « Se déconnecter », ou écrivez au support depuis l\'e-mail ou le numéro lié à votre compte ; nous vérifierons et traiterons la demande.',
