  'عند إضافة أكثر من وحدة معًا: يُحفظ عدد العدادات لكل وحدة، وأرقامها تُكتب لكل وحدة من «تعديل الوحدات».': 'En ajoutant plusieurs unités à la fois, le nombre de compteurs est enregistré pour chaque unité ; saisissez leurs numéros pour chaque unité depuis « Modifier les unités ».',
