  'تبقى كل المصروفات المسجّلة كما هي. هل تريد المتابعة؟': 'Toutes les dépenses enregistrées restent inchangées. Continuer ?',
  'ستعود العهدة إليك وتتوقف صلاحية الصرف عند الطرف الآخر. تبقى كل المصروفات المسجّلة كما هي. هل تريد المتابعة؟': 'La garde vous revient et l\'autre partie ne peut plus dépenser. Toutes les dépenses enregistrées restent inchangées. Continuer ?',
  'تسوية العهدة قبل الإلغاء': 'Régler la garde avant l\'annulation',
  'لا تُلغى العهدة بدون تسوية. اكتب سبب التسوية ثم اختر إلغاء العهدة أو تسويتها وأرشفتها.': 'La garde ne peut pas être annulée sans règlement. Indiquez le motif du règlement, puis choisissez d\'annuler la garde ou de la régler et l\'archiver.',
