  'إدارة العهدة\nوالمصروفات': 'Garde\net dépenses',
  '، ثم يعود حسابك إلى الباقة الأساسية وتبقى بياناتك محفوظة. لا تُسترد المبالغ المدفوعة عن المدة الحالية.': ', puis votre compte revient au forfait de base et vos données sont conservées. Les montants payés pour la période en cours ne sont pas remboursables.',
  'آخر تحديث: 17 أكتوبر 2026': 'Dernière mise à jour : 17 octobre 2026',
  'أضفه من تعديل الملف الشخصي': 'Ajoutez-la depuis Modifier le profil',
  'أُعيد تفعيل التجديد التلقائي': 'Renouvellement automatique réactivé',
  'أُلغي التجديد — الاشتراك فعّال حتى': 'Renouvellement annulé — abonnement actif jusqu\'au',
  'إعادة تفعيل التجديد': 'Réactiver le renouvellement',
  'إعادة تفعيل التجديد التلقائي': 'Réactiver le renouvellement automatique',
  'إلغاء التجديد': 'Annuler le renouvellement',
  'إلغاء التجديد التلقائي': 'Annuler le renouvellement automatique',
  'إيقاف الحساب وحذفه': 'Suspension et suppression du compte',
  'اختيار من التقويم': 'Choisir dans le calendrier',
  'اكتب «تاريخ الميلاد» في تعديل الملف الشخصي — والباقي يحسبه التطبيق لك.': 'Saisissez votre date de naissance dans Modifier le profil — l\'application calcule le reste.',
  'الأسعار المعروضة نهائية وتشمل ضريبة القيمة المضافة حيث تنطبق، ولا يضيف التطبيق أي رسوم أخرى. قد يطبّق البنك أو المتجر رسوم تحويل العملة.': 'Les prix affichés sont définitifs et incluent la TVA le cas échéant ; l\'application n\'ajoute aucun autre frais. Votre banque ou la boutique peut appliquer des frais de conversion.',
  'الأهلية والحساب': 'Éligibilité et compte',
  'الاستخدام المقبول': 'Utilisation acceptable',
  'الاسترداد': 'Remboursements',
  'الاشتراك الشهري أو السنوي يتجدد تلقائيًا في نهاية كل مدة بنفس السعر حتى تلغي التجديد. الهدية لا تتجدد وتنتهي بنهاية مدتها.': 'L\'abonnement mensuel ou annuel se renouvelle automatiquement à la fin de chaque période au même prix jusqu\'à l\'annulation du renouvellement. Les cadeaux ne se renouvellent pas.',
  'الاشتراك المُهدى يبدأ يوم تفعيل كوده من المُهدى إليه، وينتهي بنهاية مدته دون تجديد. لا تُسترد قيمة الهدية بعد شرائها أو تفعيلها، ولا تُستبدل نقدًا.': 'Un abonnement offert commence le jour où le bénéficiaire active son code et se termine à la fin de sa période sans renouvellement. Les cadeaux ne sont ni remboursables après achat ou activation, ni échangeables contre de l\'argent.',
  'التجديد التلقائي': 'Renouvellement automatique',
  'التطبيق أداة لتنظيم وتسجيل الأموال والالتزامات والأصول والعلاقات. ما يعرضه من أرقام وتنبيهات وتقارير مبني على ما تدخله أنت، ولا يُعد استشارة مالية أو قانونية أو محاسبية أو ضريبية.': 'L\'application est un outil pour organiser et enregistrer argent, engagements, actifs et relations. Ses chiffres, alertes et rapports reposent sur vos saisies et ne constituent pas un conseil financier, juridique, comptable ou fiscal.',
  'التعديلات على الشروط': 'Modifications des conditions',
  'التواصل بشأن المدفوعات': 'Questions sur les paiements',
  'التوفر والتعديلات على الخدمة': 'Disponibilité et modifications du service',
  'الدفع داخل التطبيق لم يُفعَّل بعد، فتُفعَّل الباقة الآن تجريبيًا بلا أي خصم. يبدأ الاشتراك فورًا ويتجدد تلقائيًا في نهاية المدة حتى تلغي التجديد، وتتغير صلاحيات الأقسام فورًا.': 'Le paiement intégré n\'est pas encore activé : le forfait est activé à titre d\'essai sans frais. L\'abonnement commence immédiatement et se renouvelle automatiquement à la fin de la période jusqu\'à l\'annulation ; les autorisations changent immédiatement.',
  'الرسوم والضرائب': 'Frais et taxes',
  'المشاركة مع مستخدمين آخرين': 'Partage avec d\'autres utilisateurs',
  'النظام الواجب التطبيق': 'Droit applicable',
  'بدأ في': 'Commencé le',
  'بعد الإلغاء': 'Après l\'annulation',
  'بنفس السعر والمدة.': 'au même prix et pour la même durée.',
  'بياناتك ومحتواك': 'Vos données et contenus',
  'تاريخ الميلاد غير صحيح — اكتبه يوم/شهر/سنة مثل 17/9/1984': 'Date de naissance invalide — saisissez-la jour/mois/année, ex. 17/9/1984',
  'تخضع هذه الشروط لأنظمة المملكة العربية السعودية، وتختص محاكمها بالنظر في أي نزاع ينشأ عنها، دون إخلال بحقوقك النظامية في بلد إقامتك.': 'Ces conditions sont régies par les lois du Royaume d\'Arabie saoudite, dont les tribunaux sont compétents pour tout litige, sans préjudice de vos droits légaux dans votre pays de résidence.',
  'تنبيه: عند إلغاء الاشتراك أو الهدية لا تُسترد المبالغ المدفوعة، ويبقى الاشتراك فعّالًا حتى نهاية مدته.': 'Remarque : l\'annulation d\'un abonnement ou d\'un cadeau ne rembourse pas les montants payés ; l\'abonnement reste actif jusqu\'à la fin de sa période.',
  'تنظّم هذه الشروط استخدامك تطبيق Fundly وخدماته. باستخدامك التطبيق فأنت توافق عليها وعلى سياسة الخصوصية، فإن لم توافق فتوقف عن الاستخدام.': 'Ces conditions régissent votre utilisation de l\'application Fundly et de ses services. En l\'utilisant, vous les acceptez ainsi que la Politique de confidentialité ; sinon, cessez de l\'utiliser.',
  'تواصل بشأن المدفوعات': 'Nous contacter au sujet des paiements',
  'تُقدَّم الخدمة «كما هي». وبالقدر الذي تسمح به الأنظمة لا نتحمل المسؤولية عن أي خسارة غير مباشرة، أو عن قرارات اتخذتها بناءً على بيانات أدخلتها، أو عن فقد بيانات محفوظة على جهازك فقط.': 'Le service est fourni « tel quel ». Dans la mesure permise par la loi, nous ne sommes pas responsables des pertes indirectes, des décisions prises sur la base de vos données ni de la perte de données stockées uniquement sur votre appareil.',
  'حدود المسؤولية': 'Limitation de responsabilité',
  'سيتجدد اشتراكك تلقائيًا في': 'Votre abonnement se renouvellera automatiquement le',
  'شروط الاستخدام': 'Conditions d\'utilisation',
  'شروط الاشتراك والدفع': 'Conditions d\'abonnement et de paiement',
  'شروط الخدمة والاشتراكات والمدفوعات': 'Conditions du service, des abonnements et des paiements',
  'طبيعة الخدمة': 'Nature du service',
  'عند إسناد عهدة أو ربط دين أو إضافة أعضاء إلى التزام مشترك، يرى الطرف الآخر العنصر المشترك وما يسجّله فيه. كل طرف مسؤول عمّا يسجّله أو يعتمده، والتطبيق وسيلة توثيق ولا يضمن وفاء أي طرف بالتزاماته تجاه الآخر.': 'Lorsque vous attribuez une garde, liez une dette ou ajoutez des membres à un engagement partagé, l\'autre partie voit l\'élément partagé et ce qui y est enregistré. Chaque partie est responsable de ce qu\'elle enregistre ou approuve ; l\'application documente et ne garantit pas l\'exécution des obligations entre les parties.',
  'قد نحدّث هذه الشروط، ونُبلغك داخل التطبيق بأي تغيير جوهري قبل سريانه. واستمرارك في الاستخدام بعد السريان يعني موافقتك على النسخة المحدّثة.': 'Nous pouvons mettre à jour ces conditions et vous informerons dans l\'application de tout changement important avant son entrée en vigueur. Continuer à utiliser l\'application vaut acceptation.',
  'لأي استفسار عن الدفع أو الفواتير أو الاسترداد راسلنا من «تواصل معنا» على بريد الدعم، مع تاريخ العملية ورقم الإصدار.': 'Pour toute question sur les paiements, factures ou remboursements, écrivez-nous depuis « Nous contacter » à l\'adresse du support, avec la date de l\'opération et la version.',
  'لأي سؤال عن هذه الشروط أو عن الاشتراكات والمدفوعات راسلنا على بريد الدعم: support@fundly.app': 'Pour toute question sur ces conditions, les abonnements ou les paiements, écrivez au support : support@fundly.app',
  'لا تُسترد المبالغ المدفوعة عن مدة بدأت، ولا قيمة الهدية بعد شرائها أو تفعيلها، إلا ما يوجبه النظام أو سياسة المتجر الذي تمت منه عملية الدفع.': 'Les montants payés pour une période commencée ne sont pas remboursables, ni les cadeaux après achat ou activation, sauf obligation légale ou politique de la boutique utilisée pour le paiement.',
  'لا يُقطع الاشتراك فورًا: يبقى فعّالًا حتى نهاية المدة المدفوعة، ثم يعود حسابك إلى الباقة الأساسية وتبقى كل بياناتك محفوظة.': 'L\'abonnement n\'est pas interrompu immédiatement : il reste actif jusqu\'à la fin de la période payée, puis votre compte revient au forfait de base et toutes vos données sont conservées.',
  'متى يبدأ الاشتراك': 'Début de l\'abonnement',
  'مفعّل': 'Activé',
  'ملغى — يبقى فعّالًا حتى نهاية المدة': 'Annulé — reste actif jusqu\'à la fin de la période',
  'من هذه الصفحة بزر «إلغاء التجديد التلقائي»، أو من إدارة الاشتراكات في متجر التطبيقات الذي دفعت منه، قبل موعد التجديد بيوم على الأقل.': 'Depuis cette page avec « Annuler le renouvellement automatique », ou depuis la gestion des abonnements de la boutique utilisée, au moins un jour avant la date de renouvellement.',
  'نعمل على أن تكون الخدمة متاحة باستمرار، لكن قد تتوقف مؤقتًا للصيانة أو لأسباب خارجة عن إرادتنا. وقد نطوّر الميزات أو نعدّلها، ونُبلغك داخل التطبيق بأي تغيير جوهري يمس اشتراكك.': 'Nous visons une disponibilité continue, mais le service peut être interrompu pour maintenance ou pour des raisons indépendantes de notre volonté. Nous pouvons faire évoluer les fonctionnalités et vous informerons de tout changement important touchant votre abonnement.',
  'هدية — لا تتجدد': 'Cadeau — ne se renouvelle pas',
  'يبدأ فور تأكيد الدفع وتُحسب مدته من يوم الدفع. والهدية تبدأ يوم تفعيل كودها من المُهدى إليه، لا يوم شرائها.': 'Il commence dès la confirmation du paiement et sa durée court à partir du jour du paiement. Un cadeau commence le jour où le bénéficiaire active son code, et non le jour de l\'achat.',
  'يبقى اشتراكك فعّالًا حتى': 'Votre abonnement reste actif jusqu\'au',
  'يتجدد تلقائيًا في': 'Se renouvelle automatiquement le',
  'يتجدد في': 'Se renouvelle le',
  'يمكنك حذف حسابك في أي وقت من الإعدادات. ويحق لنا تعليق الحساب أو إيقافه عند مخالفة هذه الشروط، مع إبلاغك بالسبب ما لم يمنع ذلك نظام.': 'Vous pouvez supprimer votre compte à tout moment depuis les paramètres. Nous pouvons suspendre ou fermer un compte qui enfreint ces conditions, en vous en indiquant la raison sauf interdiction légale.',
  'يوم/شهر/سنة — مثل 17/9/1984': 'Jour/mois/année — ex. 17/9/1984',
  'يُمنع استخدام التطبيق في أي نشاط مخالف للأنظمة أو في الاحتيال أو انتحال الشخصية، أو محاولة الوصول إلى حسابات أو بيانات غيرك، أو تعطيل الخدمة، أو نسخ التطبيق أو تفكيكه أو إعادة بيعه.': 'Il est interdit d\'utiliser l\'application pour toute activité illégale, fraude ou usurpation d\'identité, de tenter d\'accéder aux comptes ou données d\'autrui, de perturber le service, ou de copier, décompiler ou revendre l\'application.',
  '• التطبيق لمن بلغ 18 عامًا.\n• أنت مسؤول عن صحة بيانات حسابك، وعن سرية كلمة المرور ورمز قفل التطبيق، وعن كل ما يتم من حسابك.\n• أبلغنا فورًا إن اشتبهت في استخدام حسابك دون إذنك.': '• L\'application est réservée aux personnes de 18 ans ou plus.\n• Vous êtes responsable de l\'exactitude des données de votre compte, de la confidentialité de votre mot de passe et de votre code de verrouillage, et de tout ce qui est fait depuis votre compte.\n• Prévenez-nous immédiatement en cas d\'utilisation suspecte de votre compte.',
  '• ما تدخله من بيانات ومستندات يبقى ملكك، وتمنحنا حق معالجته بالقدر اللازم لتقديم الخدمة فقط وفق سياسة الخصوصية.\n• أنت مسؤول عن مشروعية ما تسجّله من بيانات أشخاص آخرين وعن حصولك على ما يلزم لذلك.': '• Les données et documents que vous saisissez restent les vôtres ; vous nous autorisez à les traiter uniquement pour fournir le service, conformément à la Politique de confidentialité.\n• Vous êtes responsable de la licéité des données de tiers que vous enregistrez et des autorisations nécessaires.',
  '• يبدأ الاشتراك فور تأكيد الدفع وتُحسب مدته من يوم الدفع.\n• يتجدد الاشتراك الشهري أو السنوي تلقائيًا بنفس السعر حتى تلغي التجديد من صفحة الاشتراكات أو من متجر التطبيقات قبل موعد التجديد بيوم على الأقل.\n• إلغاء التجديد لا يقطع الاشتراك فورًا: يبقى فعّالًا حتى نهاية المدة المدفوعة ثم يعود الحساب إلى الباقة الأساسية وتبقى البيانات محفوظة.\n• لا تُسترد المبالغ المدفوعة عن مدة بدأت، إلا ما يوجبه النظام أو سياسة المتجر الذي تمت منه عملية الدفع.\n• الأسعار المعروضة نهائية وتشمل ضريبة القيمة المضافة حيث تنطبق، وقد يطبّق البنك أو المتجر رسوم تحويل العملة.': '• L\'abonnement commence dès la confirmation du paiement et sa durée court à partir du jour du paiement.\n• L\'abonnement mensuel ou annuel se renouvelle automatiquement au même prix jusqu\'à l\'annulation depuis la page Abonnements ou la boutique, au moins un jour avant le renouvellement.\n• L\'annulation du renouvellement n\'interrompt pas l\'abonnement : il reste actif jusqu\'à la fin de la période payée, puis le compte revient au forfait de base et les données sont conservées.\n• Les montants payés pour une période commencée ne sont pas remboursables, sauf obligation légale ou politique de la boutique utilisée.\n• Les prix affichés sont définitifs et incluent la TVA le cas échéant ; votre banque ou la boutique peut appliquer des frais de conversion.',
  'أضف شعارك من «المزيد» ← «التوقيع الإلكتروني والختم» ليظهر أعلى كل نموذج': 'Ajoutez votre logo depuis « Plus » → « Signature et cachet électroniques » pour l\'afficher en haut de chaque modèle',
