  'اضغط على السجل لإدارته حسب صلاحياتك، والعقار يُفتح في قسمه — وكل ما تفعله يصل إشعاره للمالك.': 'Appuyez sur un enregistrement pour le gérer selon vos autorisations ; les biens s’ouvrent dans leur section — le propriétaire est notifié de tout ce que vous faites.',
